            customer_ids = [k for k in coords if k != depot]
        elif isinstance(coords, (list, tuple)):
            customer_ids = list(range(len(coords)))
            if depot in customer_ids:
                customer_ids.remove(depot)
        elif isinstance(demands, (list, tuple)):
            customer_ids = list(range(len(demands)))
            if depot in customer_ids:
                customer_ids.remove(depot)
        else:
            customer_ids = []
    customer_ids = [c for c in list(customer_ids) if c != depot]
    customer_ids.sort()

    def dem(c):
        if isinstance(demands, dict):
            return demands.get(c, 1)
        if isinstance(demands, (list, tuple)):
            if 0 <= c < len(demands):
                return demands[c]
            if 1 <= c <= len(demands):
                return demands[c - 1]
        return 1

    def coord(n):
        if isinstance(coords, dict):
            return coords.get(n)
        if isinstance(coords, (list, tuple)):
            if 0 <= n < len(coords):
                return coords[n]
            if 1 <= n <= len(coords):
                return coords[n - 1]
        return None

    def dist(a, b):
        if distm is not None:
            try:
                return distm[a][b]
            except Exception:
                try:
                    return distm[b][a]
                except Exception:
                    pass
        pa = coord(a)
        pb = coord(b)
        if pa is not None and pb is not None:
            dx = pa[0] - pb[0]
            dy = pa[1] - pb[1]
            return (dx * dx + dy * dy) ** 0.5
        return abs(a - b)

    def load(r):
        s = 0
        for c in r:
            s += dem(c)
        return s

    def cost(r):
        if not r:
            return 0
        t = dist(depot, r[0])
        for i in range(len(r) - 1):
            t += dist(r[i], r[i + 1])
        return t + dist(r[-1], depot)

    unr = set(customer_ids)
    routes = []
    while unr:
        seed = None
        best = None
        for c in unr:
            k = (dist(depot, c), dem(c), c)
            if best is None or k > best:
                best = k
                seed = c
        r = [seed]
        unr.remove(seed)
        l = dem(seed)
        while True:
            last = r[-1]
            cand = None
            bestk = None
            for c in unr:
                dc = dem(c)
                if capacity is not None and l + dc > capacity:
                    continue
                k = (dist(last, c) + dist(c, depot) - dist(last, depot), dist(depot, c), dc, c)
                if bestk is None or k < bestk:
                    bestk = k
                    cand = c
            if cand is None:
                break
            r.append(cand)
            unr.remove(cand)
            l += dem(cand)
        routes.append(r)

    def two_opt(r):
        n = len(r)
        if n < 4:
            return r[:]
        best = r[:]
        bestc = cost(best)
        improved = True
        while improved:
            improved = False
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    cand = best[:i + 1] + best[i + 1:j + 1][::-1] + best[j + 1:]
                    cc = cost(cand)
                    if cc + 1e-12 < bestc:
                        best, bestc, improved = cand, cc, True
                        break
                if improved:
                    break
        return best

    routes = [two_opt(r) for r in routes if r]
    changed = True
    rounds = 0
    while changed and rounds < 60:
        rounds += 1
        changed = False
        for i in range(len(routes)):
            if changed:
                break
            for j in range(len(routes)):
                if i == j:
                    continue
                ri = routes[i]
                rj = routes[j]
                li = load(ri)
                lj = load(rj)
                base = cost(ri) + cost(rj)
                for a, c in enumerate(ri):
                    dc = dem(c)
                    if capacity is not None and lj + dc > capacity:
                        continue
                    nri = ri[:a] + ri[a + 1:]
                    if not nri:
                        continue
                    for p in range(len(rj) + 1):
                        nrj = rj[:p] + [c] + rj[p:]
                        if cost(nri) + cost(nrj) + 1e-12 < base:
                            routes[i] = two_opt(nri)
                            routes[j] = two_opt(nrj)
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
        if changed:
            continue
        for i in range(len(routes)):
            if changed:
                break
            for j in range(i + 1, len(routes)):
                ri = routes[i]
                rj = routes[j]
                li = load(ri)
                lj = load(rj)
                base = cost(ri) + cost(rj)
                for a, ca in enumerate(ri):
                    for b, cb in enumerate(rj):
                        nai = li - dem(ca) + dem(cb)
                        naj = lj - dem(cb) + dem(ca)
                        if capacity is not None and (nai > capacity or naj > capacity):
                            continue
                        nri = ri[:a] + [cb] + ri[a + 1:]
                        nrj = rj[:b] + [ca] + rj[b + 1:]
                        if cost(nri) + cost(nrj) + 1e-12 < base:
                            routes[i] = two_opt(nri)
                            routes[j] = two_opt(nrj)
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break

    out = []
    seen = set()
    for r in routes:
        rr = []
        for c in r:
            if c != depot and c not in seen:
                rr.append(c)
                seen.add(c)
        if rr:
            out.append(rr)

    for c in customer_ids:
        if c in seen:
            continue
        placed = False
        for r in out:
            if capacity is None or load(r) + dem(c) <= capacity:
                bestp = 0
                bestc = None
                for p in range(len(r) + 1):
                    cc = cost(r[:p] + [c] + r[p:])
                    if bestc is None or cc < bestc:
                        bestc = cc
                        bestp = p
                r[:] = r[:bestp] + [c] + r[bestp:]
                placed = True
                break
        if not placed:
            out.append([c])
    return out
